INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e81012dd-caa6-5f75-a384-71d03bc84389', 'Kenya Work Injury Benefits Act', 'The Work Injury Benefits Act', 'This document outlines an Act of the Kenyan Parliament to provide for compensation to employees for work related injuries and diseases contracted in the course of their employment and for connected purposes.', 'This document outlines an Act of the Kenyan Parliament to provide for compensation to employees for work related injuries and diseases contracted in the course of their employment and for connected purposes.', 'This document outlines an Act of the Kenyan Parliament to provide for compensation to employees for work related injuries and diseases contracted in the course of their employment and for connected purposes.', 'Kenya', 'nature', 'in_force', '2007-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_21', ARRAY['sdg8', 'sdg14', 'kenya', 'other sustainability policy', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('99e767b5-2aa7-55af-8e09-3821d37fbe9b', 'Kenya Waste Management Regulations', 'Waste Management Regulations, 2006', 'The purpose of the regulations is to provide for guidelines, procedures and standards for the environmental governance to ensure compliance. The regulations also provide for licensing, monitoring and enforcement.', 'The purpose of the regulations is to provide for guidelines, procedures and standards for the environmental governance to ensure compliance. The regulations also provide for licensing, monitoring and enforcement.', 'The purpose of the regulations is to provide for guidelines, procedures and standards for the environmental governance to ensure compliance. The regulations also provide for licensing, monitoring and enforcement.', 'Kenya', 'climate', 'in_force', '2006-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_14', ARRAY['other sustainability policy', 'kenya', 'regulations', 'sdg11', 'mandatory', 'sdg16', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9a259a52-2109-59b5-ae0a-c26b704bfdd0', 'Kenya Water Quality Regulations', 'Water Quality Regulations', 'These Regulations shall apply to drinking water, water used for industrial purposes, water used for agricultural purposes, water used for recreational purposes, water used for fisheries and wildlife, and water used for any other purposes.', 'These Regulations shall apply to drinking water, water used for industrial purposes, water used for agricultural purposes, water used for recreational purposes, water used for fisheries and wildlife, and water used for any other purposes.', 'These Regulations shall apply to drinking water, water used for industrial purposes, water used for agricultural purposes, water used for recreational purposes, water used for fisheries and wildlife, and water used for any other purposes.', 'Kenya', 'nature', 'in_force', '2006-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_15', ARRAY['sdg2', 'sdg14', 'kenya', 'other sustainability policy', 'regulations', 'sdg9', 'mandatory', 'sdg6', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8feb3970-4589-5cda-be7e-88abf5516227', 'Kenya Central Depositories Act', 'The Central Depositories Act', 'An Act of Parliament to facilitate the establishment, operation and. regulation of central depositories, to provide for the immobilisation. and eventual dematerialisation of, and dealings in, securities deposited.', 'An Act of Parliament to facilitate the establishment, operation and. regulation of central depositories, to provide for the immobilisation. and eventual dematerialisation of, and dealings in, securities deposited.', 'An Act of Parliament to facilitate the establishment, operation and. regulation of central depositories, to provide for the immobilisation. and eventual dematerialisation of, and dealings in, securities deposited.', 'Kenya', 'governance', 'in_force', '2004-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_6', ARRAY['other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2371f830-bad9-5e87-9f90-d4ae29bc9431', 'Kenya Environmental (Impact Assessment and Audit) Regulations', 'The Environmental (Impact Assessment and Audit) Regulations, 2003', 'These Regulations, made under section 147 of the Environmental Management and Co-ordination Act, contain rules relative to content and procedures of an environmental impact assessment in the sense of section 58 of the Act, contain rules relative to environmental impact audit and monitoring and strategic environmental assessment and regulate some other matters such as appeal and registration of information regarding environmental impact assessment.', 'These Regulations, made under section 147 of the Environmental Management and Co-ordination Act, contain rules relative to content and procedures of an environmental impact assessment in the sense of section 58 of the Act, contain rules relative to environmental impact audit and monitoring and strategic environmental assessment and regulate some other matters such as appeal and registration of information regarding environmental impact assessment.', 'These Regulations, made under section 147 of the Environmental Management and Co-ordination Act, contain rules relative to content and procedures of an environmental impact assessment in the sense of section 58 of the Act, contain rules relative to environmental impact audit and monitoring and strategic environmental assessment and regulate some other matters such as appeal and registration of information regarding environmental impact assessment.', 'Kenya', 'climate', 'in_force', '2003-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_13', ARRAY['sdg2', 'other sustainability policy', 'kenya', 'regulations', 'sdg7', 'sdg11', 'sdg9', 'mandatory', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4ac49b78-b19c-57b7-a333-d4e70561b628', 'Kosovo Law L-250 Law on Climate Change', 'Law No. 08/L-250 Law on Climate Change', 'The Law No. 08/L-250 on Climate Change in Kosovo aims to define state authorities'' duties in mitigating climate change effects, aligning with international agreements. It applies to various sectors impacting climate change and establishes the National Council for Climate Change to oversee policy measures and emissions reduction. Target audience: state authorities, operators in key sectors.', 'The Law No. 08/L-250 on Climate Change in Kosovo aims to define state authorities'' duties in mitigating climate change effects, aligning with international agreements. It applies to various sectors impacting climate change and establishes the National Council for Climate Change to oversee policy measures and emissions reduction. Target audience: state authorities, operators in key sectors.', 'The Law No. 08/L-250 on Climate Change in Kosovo aims to define state authorities'' duties in mitigating climate change effects, aligning with international agreements. It applies to various sectors impacting climate change and establishes the National Council for Climate Change to oversee policy measures and emissions reduction. Target audience: state authorities, operators in key sectors.', 'Kosovo', 'climate', 'in_force', '2024-01-01'::date, 'Kosovo', 'https://www.carrotsandsticks.org/policies/94_3', ARRAY['kosovo', 'mandatory', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('da008df7-1e26-5611-8c02-8ad8fcdd3581', 'Kosovo Law L-209 on Sustainable Investments', 'Law No. 08/L-209 on Sustainable Investments', 'The Law No. 08/L-209 on Sustainable Investments in Kosovo aims to promote, protect, and prioritize sustainable investments and exports. It defines investor rights and obligations, including the screening of foreign direct investments. Key entities involved are investors, public institutions, and agencies supporting investments and exports.', 'The Law No. 08/L-209 on Sustainable Investments in Kosovo aims to promote, protect, and prioritize sustainable investments and exports. It defines investor rights and obligations, including the screening of foreign direct investments. Key entities involved are investors, public institutions, and agencies supporting investments and exports.', 'The Law No. 08/L-209 on Sustainable Investments in Kosovo aims to promote, protect, and prioritize sustainable investments and exports. It defines investor rights and obligations, including the screening of foreign direct investments. Key entities involved are investors, public institutions, and agencies supporting investments and exports.', 'Kosovo', 'climate', 'in_force', '2024-01-01'::date, 'Kosovo', 'https://www.carrotsandsticks.org/policies/94_4', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'kosovo']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4dde0a3d-aec5-5d50-b5b6-b56ec3d263be', 'Kosovo Law L-258 on the promotion of the use', 'Law No. 08/L-258 on the promotion of the use of reneweble energy sources', 'Law No. 08/L-258 in Kosovo promotes renewable energy use to increase energy security, protect the environment, and create employment opportunities. It sets targets, defines responsibilities, and establishes support schemes for renewable energy sources, including biofuels and biomass. The policy applies to energy stakeholders and consumers in Kosovo.', 'Law No. 08/L-258 in Kosovo promotes renewable energy use to increase energy security, protect the environment, and create employment opportunities. It sets targets, defines responsibilities, and establishes support schemes for renewable energy sources, including biofuels and biomass. The policy applies to energy stakeholders and consumers in Kosovo.', 'Law No. 08/L-258 in Kosovo promotes renewable energy use to increase energy security, protect the environment, and create employment opportunities. It sets targets, defines responsibilities, and establishes support schemes for renewable energy sources, including biofuels and biomass. The policy applies to energy stakeholders and consumers in Kosovo.', 'Kosovo', 'climate', 'in_force', '2024-01-01'::date, 'Kosovo', 'https://www.carrotsandsticks.org/policies/94_5', ARRAY['sdg8', 'regulations', 'sdg7', 'mandatory', 'kosovo']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2922e5de-41df-521c-8f5c-9d04f8de745a', 'Kosovo Law Nr. 08/L-242 on the energy performance of', 'Law Nr. 08/L-242 on the energy performance of buildings', 'Kosovo''s Law Nr. 08/L-242 aims to enhance building energy performance, aligning with EU directives. It sets standards for new and existing buildings, mandates energy certification, and establishes a system for inspections and expert licensing. Targeting building owners, constructors, and energy auditors to improve energy efficiency.', 'Kosovo''s Law Nr. 08/L-242 aims to enhance building energy performance, aligning with EU directives. It sets standards for new and existing buildings, mandates energy certification, and establishes a system for inspections and expert licensing. Targeting building owners, constructors, and energy auditors to improve energy efficiency.', 'Kosovo''s Law Nr. 08/L-242 aims to enhance building energy performance, aligning with EU directives. It sets standards for new and existing buildings, mandates energy certification, and establishes a system for inspections and expert licensing. Targeting building owners, constructors, and energy auditors to improve energy efficiency.', 'Kosovo', 'climate', 'in_force', '2024-01-01'::date, 'Kosovo', 'https://www.carrotsandsticks.org/policies/94_6', ARRAY['sdg7', 'kosovo', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42e74f3f-a72f-56ff-94d0-59b333f69814', 'Kosovo Law No.03/L –212 Law on Labour', 'Law No.03/L –212 Law on Labour, 2010', 'This Law aims at regulating the rights and obligations deriving from employment relationship, as defined by this Law.', 'This Law aims at regulating the rights and obligations deriving from employment relationship, as defined by this Law.', 'This Law aims at regulating the rights and obligations deriving from employment relationship, as defined by this Law.', 'Kosovo', 'social', 'in_force', '2010-01-01'::date, 'Kosovo', 'https://www.carrotsandsticks.org/policies/94_2', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'kosovo']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dcc7e252-2c83-5d26-932a-03534e905f5a', 'Kosovo Occupational Safety, Health and the Working Environment', 'Law No. 2003/19 on Occupational Safety, Health and the Working Environment.', 'The objective of this Law is to prevent occupational injuries and diseases at the workplace and to protect the working environment.', 'The objective of this Law is to prevent occupational injuries and diseases at the workplace and to protect the working environment.', 'The objective of this Law is to prevent occupational injuries and diseases at the workplace and to protect the working environment.', 'Kosovo', 'nature', 'in_force', '2003-01-01'::date, 'Kosovo', 'https://www.carrotsandsticks.org/policies/94_1', ARRAY['sdg8', 'sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'sdg3', 'kosovo']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('87f2ae77-2c0d-5d6c-ade3-6a525e820e77', 'Kuwait Unified Direction for a Sustainable Future', 'Unified Direction for a Sustainable Future, 2021', 'This guide proposes an initial set of corporate sustainability indicators that are in line with the State of Kuwait’s sustainable development ambitions as set out by the Kuwait Vision 2035 and the “New Kuwait” National Development Plan 1. This guide is also aligned with the Sustainable Stock Exchange Initiative (SSE) and the World Federation of Exchanges’ (WFE) recommendations, and is intended for all issuers listed on Boursa Kuwait, whereby applying all stipulated terms is optional.', 'This guide proposes an initial set of corporate sustainability indicators that are in line with the State of Kuwait’s sustainable development ambitions as set out by the Kuwait Vision 2035 and the “New Kuwait” National Development Plan 1. This guide is also aligned with the Sustainable Stock Exchange Initiative (SSE) and the World Federation of Exchanges’ (WFE) recommendations, and is intended for all issuers listed on Boursa Kuwait, whereby applying all stipulated terms is optional.', 'This guide proposes an initial set of corporate sustainability indicators that are in line with the State of Kuwait’s sustainable development ambitions as set out by the Kuwait Vision 2035 and the “New Kuwait” National Development Plan 1. This guide is also aligned with the Sustainable Stock Exchange Initiative (SSE) and the World Federation of Exchanges’ (WFE) recommendations, and is intended for all issuers listed on Boursa Kuwait, whereby applying all stipulated terms is optional.', 'Kuwait', 'climate', 'in_force', '2021-01-01'::date, 'Kuwait', 'https://www.carrotsandsticks.org/policies/95_2', ARRAY['guidance_frameworks', 'sdg13', 'kuwait', 'mandatory', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b41e3c1c-beed-543d-b61a-6769820d0d1f', 'Kuwait Sustainability Disclosure Guide', 'Sustainability Disclosure Guide, 2017', 'This guide proposes an initial set of 26 sustainability indicators that are in line the State of Kuwait''s sustainable development ambitions as set out by the Kuwait Vision 2035 and the National Development Plan “New Kuwait”. This guide is also aligned with the recommendations of the Sustainable Stock Exchanges Initiative (SSEI) and the World Federation of Exchanges (WFE).', 'This guide proposes an initial set of 26 sustainability indicators that are in line the State of Kuwait''s sustainable development ambitions as set out by the Kuwait Vision 2035 and the National Development Plan “New Kuwait”. This guide is also aligned with the recommendations of the Sustainable Stock Exchanges Initiative (SSEI) and the World Federation of Exchanges (WFE).', 'This guide proposes an initial set of 26 sustainability indicators that are in line the State of Kuwait''s sustainable development ambitions as set out by the Kuwait Vision 2035 and the National Development Plan “New Kuwait”. This guide is also aligned with the recommendations of the Sustainable Stock Exchanges Initiative (SSEI) and the World Federation of Exchanges (WFE).', 'Kuwait', 'climate', 'in_force', '2017-01-01'::date, 'Kuwait', 'https://www.carrotsandsticks.org/policies/95_1', ARRAY['guidance_frameworks', 'kuwait', 'sdg7', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ec80c46d-b740-5418-a915-c6f11881210d', 'Kuwait Executive Bylaws Module Fifteen Corporate Governance', 'The Executive Bylaws Module Fifteen Corporate Governance', 'The purpose of the module is to enhance corporate governance practices in Kuwaiti companies and protect the rights of shareholders. The module sets out regulations related to the board of directors, shareholders, auditing, and disclosure. Some of the key provisions of the module include requirements for companies to have at least three independent directors on their board, the establishment of an audit committee and a risk management committee, and the disclosure of information related to board members and executive compensation. The module also outlines penalties for non-compliance with the regulations.', 'The purpose of the module is to enhance corporate governance practices in Kuwaiti companies and protect the rights of shareholders. The module sets out regulations related to the board of directors, shareholders, auditing, and disclosure. Some of the key provisions of the module include requirements for companies to have at least three independent directors on their board, the establishment of an audit committee and a risk management committee, and the disclosure of information related to board members and executive compensation. The module also outlines penalties for non-compliance with the regulations.', 'The purpose of the module is to enhance corporate governance practices in Kuwaiti companies and protect the rights of shareholders. The module sets out regulations related to the board of directors, shareholders, auditing, and disclosure. Some of the key provisions of the module include requirements for companies to have at least three independent directors on their board, the establishment of an audit committee and a risk management committee, and the disclosure of information related to board members and executive compensation. The module also outlines penalties for non-compliance with the regulations.', 'Kuwait', 'governance', 'in_force', '2015-01-01'::date, 'Kuwait', 'https://www.carrotsandsticks.org/policies/95_3', ARRAY['kuwait', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('120c102f-412d-5d4e-acc4-b0d5f5c2538a', 'Kyrgyzstan compiling and publishing reports on sustainability, social responsibility', 'Guidance for compiling and publishing reports on sustainability, social responsibility and corporate governance criteria', 'The Kyrgyzstan policy provides guidance for compiling and publishing reports on sustainability, social responsibility, and corporate governance criteria. It aims to align companies with international ESG standards, improve transparency, and support sustainable development. Mandatory for certain companies, voluntary for others, with a focus on stakeholders, UN initiatives, and best practices.', 'The Kyrgyzstan policy provides guidance for compiling and publishing reports on sustainability, social responsibility, and corporate governance criteria. It aims to align companies with international ESG standards, improve transparency, and support sustainable development. Mandatory for certain companies, voluntary for others, with a focus on stakeholders, UN initiatives, and best practices.', 'The Kyrgyzstan policy provides guidance for compiling and publishing reports on sustainability, social responsibility, and corporate governance criteria. It aims to align companies with international ESG standards, improve transparency, and support sustainable development. Mandatory for certain companies, voluntary for others, with a focus on stakeholders, UN initiatives, and best practices.', 'Kyrgyzstan', 'climate', 'in_force', '2023-01-01'::date, 'Kyrgyzstan', 'https://www.carrotsandsticks.org/policies/199_1', ARRAY['kyrgyzstan', 'guidance_frameworks', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('27995544-8ae9-5dc1-aa3c-d64b808ae843', 'Laos Corporate Governance for Listed Companies', 'Guidelines on Corporate Governance for Listed Companies, 2021', 'The Guidelines have set a transition period of three years after its official promulgation, meaning companies can apply them on a voluntary basis during this period. Companies that are ready can implement the Guidelines immediately. Following the transition period, companies shall apply the Guidelines under the “comply or explain” approach, meaning that if companies cannot comply with the Guidelines, they must explain any non-compliance and the respective reasoning in their annual reports. The provisions of these Guidelines shall apply to all listed companies on a “comply or explain” basis, except when an element of the Guidelines is already enshrined in law. In the latter case, the law/regulation must be fully applied and complied with.', 'The Guidelines have set a transition period of three years after its official promulgation, meaning companies can apply them on a voluntary basis during this period. Companies that are ready can implement the Guidelines immediately. Following the transition period, companies shall apply the Guidelines under the “comply or explain” approach, meaning that if companies cannot comply with the Guidelines, they must explain any non-compliance and the respective reasoning in their annual reports. The provisions of these Guidelines shall apply to all listed companies on a “comply or explain” basis, except when an element of the Guidelines is already enshrined in law. In the latter case, the law/regulation must be fully applied and complied with.', 'The Guidelines have set a transition period of three years after its official promulgation, meaning companies can apply them on a voluntary basis during this period. Companies that are ready can implement the Guidelines immediately. Following the transition period, companies shall apply the Guidelines under the “comply or explain” approach, meaning that if companies cannot comply with the Guidelines, they must explain any non-compliance and the respective reasoning in their annual reports. The provisions of these Guidelines shall apply to all listed companies on a “comply or explain” basis, except when an element of the Guidelines is already enshrined in law. In the latter case, the law/regulation must be fully applied and complied with.', 'Laos', 'climate', 'in_force', '2021-01-01'::date, 'Laos', 'https://www.carrotsandsticks.org/policies/97_1', ARRAY['guidance_frameworks', 'sdg16', 'laos', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('04145b57-69ab-5d7e-beb9-9e06e3661b1e', 'Latvia Amendments to the Sustainability Information Disclosure Law', 'Amendments to the Sustainability Information Disclosure Law', 'Latvia''s 2025 amendments to the Sustainability Information Disclosure Law emphasize replacing "management" with "sustainability" in specified sections and aligning with EU directives on corporate sustainability reporting. The law aims to enhance transparency and compliance with international standards for corporate reporting. Target audience: businesses operating in Latvia.', 'Latvia''s 2025 amendments to the Sustainability Information Disclosure Law emphasize replacing "management" with "sustainability" in specified sections and aligning with EU directives on corporate sustainability reporting. The law aims to enhance transparency and compliance with international standards for corporate reporting. Target audience: businesses operating in Latvia.', 'Latvia''s 2025 amendments to the Sustainability Information Disclosure Law emphasize replacing "management" with "sustainability" in specified sections and aligning with EU directives on corporate sustainability reporting. The law aims to enhance transparency and compliance with international standards for corporate reporting. Target audience: businesses operating in Latvia.', 'Latvia', 'climate', 'in_force', '2025-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_5', ARRAY['sdg16', 'mandatory', 'latvia', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a70db706-4514-5426-b054-691ee1a0f5b6', 'Latvia Amendments to the Law "On Pollution"', 'Amendments to the Law "On Pollution"', 'Latvia''s 2025 amendments to the "Pollution Law" rename the environmental monitoring authority, define emission quotas, and introduce regulations for air and maritime operators. The policy targets entities emitting greenhouse gases and aims to enhance environmental protection and emissions monitoring in the country.', 'Latvia''s 2025 amendments to the "Pollution Law" rename the environmental monitoring authority, define emission quotas, and introduce regulations for air and maritime operators. The policy targets entities emitting greenhouse gases and aims to enhance environmental protection and emissions monitoring in the country.', 'Latvia''s 2025 amendments to the "Pollution Law" rename the environmental monitoring authority, define emission quotas, and introduce regulations for air and maritime operators. The policy targets entities emitting greenhouse gases and aims to enhance environmental protection and emissions monitoring in the country.', 'Latvia', 'climate', 'in_force', '2025-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_6', ARRAY['mandatory', 'latvia', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7d8875c8-e96a-5a30-8971-685f7016852e', 'Latvia Climate Resilience and Economic Sustainability Law', 'Climate Resilience and Economic Sustainability Law', 'Latvia''s 2025 Climate Resilience and Economic Sustainability Law aims to achieve climate neutrality by 2050, aligning with EU and international commitments. Key provisions include setting emission reduction targets for various sectors and promoting climate adaptation. Target audience includes government agencies, policymakers, and stakeholders involved in climate policy.', 'Latvia''s 2025 Climate Resilience and Economic Sustainability Law aims to achieve climate neutrality by 2050, aligning with EU and international commitments. Key provisions include setting emission reduction targets for various sectors and promoting climate adaptation. Target audience includes government agencies, policymakers, and stakeholders involved in climate policy.', 'Latvia''s 2025 Climate Resilience and Economic Sustainability Law aims to achieve climate neutrality by 2050, aligning with EU and international commitments. Key provisions include setting emission reduction targets for various sectors and promoting climate adaptation. Target audience includes government agencies, policymakers, and stakeholders involved in climate policy.', 'Latvia', 'climate', 'in_force', '2025-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_7', ARRAY['mandatory', 'latvia', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a726f4e5-da79-5b2d-a63c-46aaf151f74f', 'Latvia Amendments to the Accounting Law', 'Amendments to the Accounting Law', 'The Amendments to the Accounting Law in Latvia, effective from October 17, 2024, introduce changes to the existing accounting regulations, particularly affecting financial market participants. Key requirements include the obligation for foreign commercial branches to prepare and publish sustainability reports alongside their confirmation reports, as stipulated in the Sustainability Information Disclosure Law. This law applies to state budget institutions and non-budget funded institutions, ensuring compliance with financial management laws. The amendments are mandatory and align with EU directives on corporate sustainability reporting.', 'The Amendments to the Accounting Law in Latvia, effective from October 17, 2024, introduce changes to the existing accounting regulations, particularly affecting financial market participants. Key requirements include the obligation for foreign commercial branches to prepare and publish sustainability reports alongside their confirmation reports, as stipulated in the Sustainability Information Disclosure Law. This law applies to state budget institutions and non-budget funded institutions, ensuring compliance with financial management laws. The amendments are mandatory and align with EU directives on corporate sustainability reporting.', 'The Amendments to the Accounting Law in Latvia, effective from October 17, 2024, introduce changes to the existing accounting regulations, particularly affecting financial market participants. Key requirements include the obligation for foreign commercial branches to prepare and publish sustainability reports alongside their confirmation reports, as stipulated in the Sustainability Information Disclosure Law. This law applies to state budget institutions and non-budget funded institutions, ensuring compliance with financial management laws. The amendments are mandatory and align with EU directives on corporate sustainability reporting.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_10', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e918741b-3340-56a8-9e89-597116267be0', 'Latvia Amendments to the Law on Annual Reports', 'Amendments to the Law on Annual Reports and Consolidated Annual Reports', 'The amendments to the Law on Annual Reports and Consolidated Annual Reports in Latvia, effective from October 17, 2024, introduce significant changes to reporting requirements for companies. Key updates include the definition of substantial intangible resources and the requirement for large and medium-sized companies to include sustainability reports in their management reports. These changes aim to enhance transparency and accountability regarding sustainability issues. The law applies to all companies whose transferable securities are listed on a regulated market, making the reporting mandatory for them.', 'The amendments to the Law on Annual Reports and Consolidated Annual Reports in Latvia, effective from October 17, 2024, introduce significant changes to reporting requirements for companies. Key updates include the definition of substantial intangible resources and the requirement for large and medium-sized companies to include sustainability reports in their management reports. These changes aim to enhance transparency and accountability regarding sustainability issues. The law applies to all companies whose transferable securities are listed on a regulated market, making the reporting mandatory for them.', 'The amendments to the Law on Annual Reports and Consolidated Annual Reports in Latvia, effective from October 17, 2024, introduce significant changes to reporting requirements for companies. Key updates include the definition of substantial intangible resources and the requirement for large and medium-sized companies to include sustainability reports in their management reports. These changes aim to enhance transparency and accountability regarding sustainability issues. The law applies to all companies whose transferable securities are listed on a regulated market, making the reporting mandatory for them.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_11', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5bca9248-c8dd-5f81-8731-92ee949fde3a', 'Latvia Amendments to the Audit Services Law', 'Amendments to the Audit Services Law', 'The Amendments to the Audit Services Law in Latvia, effective from October 17, 2024, aim to update the provisions related to audit services and sustainability reporting. Key requirements include the introduction of sustainability assurance services, which must be provided by certified auditors. The amendments apply to all auditors and auditing firms operating in Latvia, establishing mandatory compliance with new definitions and responsibilities regarding sustainability reports. This law is part of a broader effort to enhance transparency and accountability in sustainability practices within the auditing profession.', 'The Amendments to the Audit Services Law in Latvia, effective from October 17, 2024, aim to update the provisions related to audit services and sustainability reporting. Key requirements include the introduction of sustainability assurance services, which must be provided by certified auditors. The amendments apply to all auditors and auditing firms operating in Latvia, establishing mandatory compliance with new definitions and responsibilities regarding sustainability reports. This law is part of a broader effort to enhance transparency and accountability in sustainability practices within the auditing profession.', 'The Amendments to the Audit Services Law in Latvia, effective from October 17, 2024, aim to update the provisions related to audit services and sustainability reporting. Key requirements include the introduction of sustainability assurance services, which must be provided by certified auditors. The amendments apply to all auditors and auditing firms operating in Latvia, establishing mandatory compliance with new definitions and responsibilities regarding sustainability reports. This law is part of a broader effort to enhance transparency and accountability in sustainability practices within the auditing profession.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_12', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2cd6e996-437c-5629-975b-ac71df9fbd4b', 'Latvia Amendments to the Financial Instruments Market Act', 'Amendments to the Financial Instruments Market Act', 'The Amendments to the Financial Instruments Market Act in Latvia, effective from October 17, 2024, aim to update regulations regarding the auditing and reporting processes for companies. Key requirements include the oversight of sustainability reports and compliance with international accounting standards. This policy applies to capital companies required to prepare sustainability reports, mandating the establishment of audit committees to ensure the integrity and completeness of these reports. The amendments are mandatory for affected entities and focus on enhancing transparency and accountability in financial reporting.', 'The Amendments to the Financial Instruments Market Act in Latvia, effective from October 17, 2024, aim to update regulations regarding the auditing and reporting processes for companies. Key requirements include the oversight of sustainability reports and compliance with international accounting standards. This policy applies to capital companies required to prepare sustainability reports, mandating the establishment of audit committees to ensure the integrity and completeness of these reports. The amendments are mandatory for affected entities and focus on enhancing transparency and accountability in financial reporting.', 'The Amendments to the Financial Instruments Market Act in Latvia, effective from October 17, 2024, aim to update regulations regarding the auditing and reporting processes for companies. Key requirements include the oversight of sustainability reports and compliance with international accounting standards. This policy applies to capital companies required to prepare sustainability reports, mandating the establishment of audit committees to ensure the integrity and completeness of these reports. The amendments are mandatory for affected entities and focus on enhancing transparency and accountability in financial reporting.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_13', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c7538a03-2f71-5071-91b6-d0d10ab3d289', 'Latvia Amendments to the Law on Credit Institutions', 'Amendments to the Law on Credit Institutions', 'The Amendments to the Law on Credit Institutions in Latvia, effective from October 17, 2024, introduce new requirements for credit institutions regarding sustainability reporting. Key provisions include the obligation for institutions to submit sustainability reports and consolidated sustainability reports in electronic format to the State Revenue Service. This law applies to all credit institutions operating in Latvia and is mandatory, aligning with EU regulations on corporate sustainability reporting. The amendments aim to enhance transparency and accountability in financial reporting related to sustainability.', 'The Amendments to the Law on Credit Institutions in Latvia, effective from October 17, 2024, introduce new requirements for credit institutions regarding sustainability reporting. Key provisions include the obligation for institutions to submit sustainability reports and consolidated sustainability reports in electronic format to the State Revenue Service. This law applies to all credit institutions operating in Latvia and is mandatory, aligning with EU regulations on corporate sustainability reporting. The amendments aim to enhance transparency and accountability in financial reporting related to sustainability.', 'The Amendments to the Law on Credit Institutions in Latvia, effective from October 17, 2024, introduce new requirements for credit institutions regarding sustainability reporting. Key provisions include the obligation for institutions to submit sustainability reports and consolidated sustainability reports in electronic format to the State Revenue Service. This law applies to all credit institutions operating in Latvia and is mandatory, aligning with EU regulations on corporate sustainability reporting. The amendments aim to enhance transparency and accountability in financial reporting related to sustainability.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_14', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8442c28d-a921-50d3-bfd1-383efb63166a', 'Latvia Amendments to the Insurance and Reinsurance Law', 'Amendments to the Insurance and Reinsurance Law', 'The amendments to the Insurance and Reinsurance Law in Latvia, effective from October 17, 2024, introduce mandatory requirements for insurance and reinsurance companies regarding sustainability reporting. These companies must prepare and submit annual financial statements and sustainability reports in accordance with the law and relevant EU regulations. The law applies to all insurance and reinsurance entities operating in Latvia, requiring them to electronically submit their reports to the State Revenue Service within specified deadlines. This legislation aims to enhance transparency and accountability in the insurance sector.', 'The amendments to the Insurance and Reinsurance Law in Latvia, effective from October 17, 2024, introduce mandatory requirements for insurance and reinsurance companies regarding sustainability reporting. These companies must prepare and submit annual financial statements and sustainability reports in accordance with the law and relevant EU regulations. The law applies to all insurance and reinsurance entities operating in Latvia, requiring them to electronically submit their reports to the State Revenue Service within specified deadlines. This legislation aims to enhance transparency and accountability in the insurance sector.', 'The amendments to the Insurance and Reinsurance Law in Latvia, effective from October 17, 2024, introduce mandatory requirements for insurance and reinsurance companies regarding sustainability reporting. These companies must prepare and submit annual financial statements and sustainability reports in accordance with the law and relevant EU regulations. The law applies to all insurance and reinsurance entities operating in Latvia, requiring them to electronically submit their reports to the State Revenue Service within specified deadlines. This legislation aims to enhance transparency and accountability in the insurance sector.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_15', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('409d3823-f8a6-5097-8e67-ad5fd58ad5cd', 'Latvia Amendments to the Law on Investment Firms', 'Amendments to the Law on Investment Firms', 'The amendments to the Law on Investment Firms in Latvia, effective from October 17, 2024, update the requirements for investment brokerage companies regarding financial reporting and sustainability disclosures. Key changes include the adoption of new international accounting standards and the introduction of mandatory sustainability reports. These amendments apply to all licensed investment brokerage firms in Latvia and establish clear guidelines for the preparation and submission of annual reports and sustainability information to the State Revenue Service. The requirements are mandatory for affected firms.', 'The amendments to the Law on Investment Firms in Latvia, effective from October 17, 2024, update the requirements for investment brokerage companies regarding financial reporting and sustainability disclosures. Key changes include the adoption of new international accounting standards and the introduction of mandatory sustainability reports. These amendments apply to all licensed investment brokerage firms in Latvia and establish clear guidelines for the preparation and submission of annual reports and sustainability information to the State Revenue Service. The requirements are mandatory for affected firms.', 'The amendments to the Law on Investment Firms in Latvia, effective from October 17, 2024, update the requirements for investment brokerage companies regarding financial reporting and sustainability disclosures. Key changes include the adoption of new international accounting standards and the introduction of mandatory sustainability reports. These amendments apply to all licensed investment brokerage firms in Latvia and establish clear guidelines for the preparation and submission of annual reports and sustainability information to the State Revenue Service. The requirements are mandatory for affected firms.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_16', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bcbbe03e-7a5d-58f5-a94b-b259e5f82677', 'Latvia Amendments to the Law on Investment Management Companies', 'Amendments to the Law on Investment Management Companies', 'The Amendments to the Law on Investment Management Companies in Latvia, effective from October 17, 2024, introduce key changes regarding sustainability reporting. It mandates that companies prepare sustainability reports in line with the Sustainability Information Disclosure Law. The amendments specify the qualifications for individuals appointed by the Bank of Latvia and outline requirements for submitting annual reports electronically, including sustainability reports. This law applies to all investment management companies operating in Latvia and establishes mandatory reporting requirements.', 'The Amendments to the Law on Investment Management Companies in Latvia, effective from October 17, 2024, introduce key changes regarding sustainability reporting. It mandates that companies prepare sustainability reports in line with the Sustainability Information Disclosure Law. The amendments specify the qualifications for individuals appointed by the Bank of Latvia and outline requirements for submitting annual reports electronically, including sustainability reports. This law applies to all investment management companies operating in Latvia and establishes mandatory reporting requirements.', 'The Amendments to the Law on Investment Management Companies in Latvia, effective from October 17, 2024, introduce key changes regarding sustainability reporting. It mandates that companies prepare sustainability reports in line with the Sustainability Information Disclosure Law. The amendments specify the qualifications for individuals appointed by the Bank of Latvia and outline requirements for submitting annual reports electronically, including sustainability reports. This law applies to all investment management companies operating in Latvia and establishes mandatory reporting requirements.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_17', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9c9ae74b-777d-50ba-b332-955f11c776c1', 'Latvia Amendments to the Private Pension Funds Act', 'Amendments to the Private Pension Funds Act', 'The amendments to the Private Pension Funds Act in Latvia, effective from October 17, 2024, introduce new requirements for pension funds regarding financial reporting and sustainability disclosures. Key changes include the obligation for pension funds to prepare annual reports in accordance with international accounting standards and to submit sustainability reports electronically. This law applies to all pension funds operating in Latvia and mandates compliance with the new reporting standards, aligning with EU regulations. The law emphasizes transparency and accountability in pension fund management.', 'The amendments to the Private Pension Funds Act in Latvia, effective from October 17, 2024, introduce new requirements for pension funds regarding financial reporting and sustainability disclosures. Key changes include the obligation for pension funds to prepare annual reports in accordance with international accounting standards and to submit sustainability reports electronically. This law applies to all pension funds operating in Latvia and mandates compliance with the new reporting standards, aligning with EU regulations. The law emphasizes transparency and accountability in pension fund management.', 'The amendments to the Private Pension Funds Act in Latvia, effective from October 17, 2024, introduce new requirements for pension funds regarding financial reporting and sustainability disclosures. Key changes include the obligation for pension funds to prepare annual reports in accordance with international accounting standards and to submit sustainability reports electronically. This law applies to all pension funds operating in Latvia and mandates compliance with the new reporting standards, aligning with EU regulations. The law emphasizes transparency and accountability in pension fund management.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_18', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('11bee1b3-c6c0-5bc1-8963-41bb77e31117', 'Latvia Regulation of 29 October 2024 on the Organization', 'Regulation No. 668 of 29 October 2024 on the Organization of Work of Sworn Auditors and Sworn Auditor Commercial Companies', 'Regulation No. 668, effective from November 5, 2024, establishes the organizational requirements for sworn auditors and sworn auditor commercial companies in Latvia. It mandates guidelines for work organization, resource planning, document management, and internal quality control for professionals providing auditing and sustainability reporting services. The regulation applies to both individual auditors and commercial companies offering these professional services, especially those serving public interest entities. Compliance with this regulation is mandatory, particularly for auditors involved in public interest structures, who must also adhere to EU Regulation No. 537/2014.', 'Regulation No. 668, effective from November 5, 2024, establishes the organizational requirements for sworn auditors and sworn auditor commercial companies in Latvia. It mandates guidelines for work organization, resource planning, document management, and internal quality control for professionals providing auditing and sustainability reporting services. The regulation applies to both individual auditors and commercial companies offering these professional services, especially those serving public interest entities. Compliance with this regulation is mandatory, particularly for auditors involved in public interest structures, who must also adhere to EU Regulation No. 537/2014.', 'Regulation No. 668, effective from November 5, 2024, establishes the organizational requirements for sworn auditors and sworn auditor commercial companies in Latvia. It mandates guidelines for work organization, resource planning, document management, and internal quality control for professionals providing auditing and sustainability reporting services. The regulation applies to both individual auditors and commercial companies offering these professional services, especially those serving public interest entities. Compliance with this regulation is mandatory, particularly for auditors involved in public interest structures, who must also adhere to EU Regulation No. 537/2014.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_19', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('729492c6-542b-5c0a-9887-37c33926104f', 'Latvia Regulation of 29 October 2024 on the Training', 'Regulation No. 669 of 29 October 2024 on the Training of Applicants for Sworn Auditors', 'Regulation No. 669 establishes the training requirements for applicants seeking to become sworn auditors in Latvia. It outlines the minimum content of the training process, which includes various subjects such as auditing, taxation, accounting, business management, and law, totaling a specified number of academic hours. The training must be completed in person, although remote learning options are available. Successful completion is necessary to obtain a certification document, which is valid for five years. This regulation is mandatory for all individuals pursuing the sworn auditor qualification.', 'Regulation No. 669 establishes the training requirements for applicants seeking to become sworn auditors in Latvia. It outlines the minimum content of the training process, which includes various subjects such as auditing, taxation, accounting, business management, and law, totaling a specified number of academic hours. The training must be completed in person, although remote learning options are available. Successful completion is necessary to obtain a certification document, which is valid for five years. This regulation is mandatory for all individuals pursuing the sworn auditor qualification.', 'Regulation No. 669 establishes the training requirements for applicants seeking to become sworn auditors in Latvia. It outlines the minimum content of the training process, which includes various subjects such as auditing, taxation, accounting, business management, and law, totaling a specified number of academic hours. The training must be completed in person, although remote learning options are available. Successful completion is necessary to obtain a certification document, which is valid for five years. This regulation is mandatory for all individuals pursuing the sworn auditor qualification.', 'Latvia', 'governance', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_20', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'mandatory', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('25443e61-8492-5df2-a834-135e4927e048', 'Latvia Sustainability Information Disclosure Law', 'Sustainability Information Disclosure Law', 'The Sustainability Information Disclosure Law in Latvia, effective from 2024, aims to provide accessible and comparable information on sustainability impact for registered commercial entities. Key requirements include reporting on sustainability issues and strategies for a sustainable economy and climate neutrality. Target entities range from large corporations to subsidiaries and filial branches.', 'The Sustainability Information Disclosure Law in Latvia, effective from 2024, aims to provide accessible and comparable information on sustainability impact for registered commercial entities. Key requirements include reporting on sustainability issues and strategies for a sustainable economy and climate neutrality. Target entities range from large corporations to subsidiaries and filial branches.', 'The Sustainability Information Disclosure Law in Latvia, effective from 2024, aims to provide accessible and comparable information on sustainability impact for registered commercial entities. Key requirements include reporting on sustainability issues and strategies for a sustainable economy and climate neutrality. Target entities range from large corporations to subsidiaries and filial branches.', 'Latvia', 'climate', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_4', ARRAY['mandatory', 'latvia', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1e492c23-2458-540c-8c19-a905196c97ca', 'Latvia ensuring a global minimum tax level for large', 'Law on ensuring a global minimum tax level for large corporate groups', 'Latvia''s 2024 law establishes a global minimum tax level for large corporate groups to prevent significant competition distortions. It defines terms and criteria for fiscal transparency, consolidation of financial statements, and outlines entities'' tax obligations within the group. Target audience includes large corporate groups and tax authorities.', 'Latvia''s 2024 law establishes a global minimum tax level for large corporate groups to prevent significant competition distortions. It defines terms and criteria for fiscal transparency, consolidation of financial statements, and outlines entities'' tax obligations within the group. Target audience includes large corporate groups and tax authorities.', 'Latvia''s 2024 law establishes a global minimum tax level for large corporate groups to prevent significant competition distortions. It defines terms and criteria for fiscal transparency, consolidation of financial statements, and outlines entities'' tax obligations within the group. Target audience includes large corporate groups and tax authorities.', 'Latvia', 'governance', 'in_force', '2024-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_9', ARRAY['sdg16', 'mandatory', 'latvia', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('34b04508-27d0-5596-b4a0-75d113fcc5b8', 'Latvia Corporate Governance Code', 'Corporate Governance Code, 2020', 'This Code consists of 17 principles which support the increase of the company value in the long term, as well as its effective management and transparency of operations. These principles are grouped into 10 sections and cover both conceptual dimensions of corporate governance, such as corporate strategy, internal culture and ethics, and more specific issues of supervisory board election and composition.', 'This Code consists of 17 principles which support the increase of the company value in the long term, as well as its effective management and transparency of operations. These principles are grouped into 10 sections and cover both conceptual dimensions of corporate governance, such as corporate strategy, internal culture and ethics, and more specific issues of supervisory board election and composition.', 'This Code consists of 17 principles which support the increase of the company value in the long term, as well as its effective management and transparency of operations. These principles are grouped into 10 sections and cover both conceptual dimensions of corporate governance, such as corporate strategy, internal culture and ethics, and more specific issues of supervisory board election and composition.', 'Latvia', 'climate', 'in_force', '2020-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_3', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2b7c6c64-bfd5-593e-925b-ac3702f851b4', 'Latvia Principles of Corporate Governance and Recommendations on their', 'Principles of Corporate Governance and Recommendations on their Implementation, 2010', 'This is the 2010 version of the Stock Exchange Recommendations which aim to facilitate the transparency of the Issuers’ business and to improve the disclosure quality, which would, in its turn, facilitate the interest of local and foreign investors about the stocks of the Issuers that are listed on the Stock Exchange, as well as the reliability of securities in the market of Latvia on the whole.', 'This is the 2010 version of the Stock Exchange Recommendations which aim to facilitate the transparency of the Issuers’ business and to improve the disclosure quality, which would, in its turn, facilitate the interest of local and foreign investors about the stocks of the Issuers that are listed on the Stock Exchange, as well as the reliability of securities in the market of Latvia on the whole.', 'This is the 2010 version of the Stock Exchange Recommendations which aim to facilitate the transparency of the Issuers’ business and to improve the disclosure quality, which would, in its turn, facilitate the interest of local and foreign investors about the stocks of the Issuers that are listed on the Stock Exchange, as well as the reliability of securities in the market of Latvia on the whole.', 'Latvia', 'climate', 'in_force', '2010-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_2', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg7', 'sdg16', 'sdg9', 'voluntary', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aa0f0eb2-7fc8-51f1-a279-6891b06c213e', 'Latvia Principles of Corporate Governance and Recommendations on their', 'Principles of Corporate Governance and Recommendations on their Implementation, 2005', 'The objective of these Recommendations is to facilitate the transparency of disclosure of Issuers’ information and to improve its quality, which would, in its turn, facilitate the interest of local and foreign investors about the stocks of the Issuers that are listed on the Stock Exchange, as well as the reliability of securities in the market of Latvia on the whole.', 'The objective of these Recommendations is to facilitate the transparency of disclosure of Issuers’ information and to improve its quality, which would, in its turn, facilitate the interest of local and foreign investors about the stocks of the Issuers that are listed on the Stock Exchange, as well as the reliability of securities in the market of Latvia on the whole.', 'The objective of these Recommendations is to facilitate the transparency of disclosure of Issuers’ information and to improve its quality, which would, in its turn, facilitate the interest of local and foreign investors about the stocks of the Issuers that are listed on the Stock Exchange, as well as the reliability of securities in the market of Latvia on the whole.', 'Latvia', 'governance', 'in_force', '2005-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_1', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg16', 'voluntary', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4197f880-8b64-56c7-b644-1b690ead6e8d', 'Latvia Labor Law', 'Labor Law', 'The Labor Law in Latvia, enacted in 2001, governs employment relationships. It establishes rights and obligations for both employers and employees, ensuring fair working conditions and equal treatment. The law applies to all employers and employees in the country, emphasizing non-discrimination and protection of workers'' rights.', 'The Labor Law in Latvia, enacted in 2001, governs employment relationships. It establishes rights and obligations for both employers and employees, ensuring fair working conditions and equal treatment. The law applies to all employers and employees in the country, emphasizing non-discrimination and protection of workers'' rights.', 'The Labor Law in Latvia, enacted in 2001, governs employment relationships. It establishes rights and obligations for both employers and employees, ensuring fair working conditions and equal treatment. The law applies to all employers and employees in the country, emphasizing non-discrimination and protection of workers'' rights.', 'Latvia', 'social', 'in_force', '2001-01-01'::date, 'Latvia', 'https://www.carrotsandsticks.org/policies/98_8', ARRAY['sdg8', 'sdg10', 'regulations', 'mandatory', 'latvia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1b6782d5-e4f5-52a0-bf1a-ef969d0eaf2c', 'Lebanon Corporate Governance Guidelines for Listed Companies', 'Corporate Governance Guidelines for Listed Companies', 'The Corporate Governance Guidelines for Listed Companies on the Beirut Stock Exchange aim at providing such companies with guidance for a sound system of corporate governance conferring upon managers, directors, shareholders and stakeholders’ incentives to always perform in the best interests of listed companies and the Lebanese economy in general.', 'The Corporate Governance Guidelines for Listed Companies on the Beirut Stock Exchange aim at providing such companies with guidance for a sound system of corporate governance conferring upon managers, directors, shareholders and stakeholders’ incentives to always perform in the best interests of listed companies and the Lebanese economy in general.', 'The Corporate Governance Guidelines for Listed Companies on the Beirut Stock Exchange aim at providing such companies with guidance for a sound system of corporate governance conferring upon managers, directors, shareholders and stakeholders’ incentives to always perform in the best interests of listed companies and the Lebanese economy in general.', 'Lebanon', 'governance', 'in_force', '2009-01-01'::date, 'Lebanon', 'https://www.carrotsandsticks.org/policies/99_1', ARRAY['guidance_frameworks', 'sdg16', 'lebanon', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b1b73d20-010a-5504-913b-3d33663a9078', 'Lebanon Lebanese Code of Corporate Governance', 'The Lebanese Code of Corporate Governance', 'This Corporate Governance Code is representative of the many ongoing efforts by the Lebanese Transparency Association towards continually improving the business environment in Lebanon.', 'This Corporate Governance Code is representative of the many ongoing efforts by the Lebanese Transparency Association towards continually improving the business environment in Lebanon.', 'This Corporate Governance Code is representative of the many ongoing efforts by the Lebanese Transparency Association towards continually improving the business environment in Lebanon.', 'Lebanon', 'governance', 'in_force', '2006-01-01'::date, 'Lebanon', 'https://www.carrotsandsticks.org/policies/99_2', ARRAY['mandatory', 'sdg16', 'lebanon', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('084c31be-10ec-5e1d-958c-c98ec63dfdc8', 'Liechtenstein Report and Motion of the Government to the', 'Report and Motion of the Government to the Parliament of the Principality of Liechtenstein Concerning the Amendment of the Law of 7 March 2024 on the Amendment of the Personal and Company Law and of the Law of 7 March 2024 on the Amendment of the Disclosure Act', 'The policy document presents Liechtenstein''s implementation of the EU''s "Stop the Clock" Directive, extending deadlines for sustainability reporting. It aims to simplify reporting obligations for businesses, with the Ministry of Society and Justice and Finance overseeing compliance. Targeted entities include companies subject to sustainability reporting requirements.', 'The policy document presents Liechtenstein''s implementation of the EU''s "Stop the Clock" Directive, extending deadlines for sustainability reporting. It aims to simplify reporting obligations for businesses, with the Ministry of Society and Justice and Finance overseeing compliance. Targeted entities include companies subject to sustainability reporting requirements.', 'The policy document presents Liechtenstein''s implementation of the EU''s "Stop the Clock" Directive, extending deadlines for sustainability reporting. It aims to simplify reporting obligations for businesses, with the Ministry of Society and Justice and Finance overseeing compliance. Targeted entities include companies subject to sustainability reporting requirements.', 'Liechtenstein', 'climate', 'in_force', '2025-01-01'::date, 'Liechtenstein', 'https://www.carrotsandsticks.org/policies/204_1', ARRAY['sdg16', 'mandatory', 'liechtenstein', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b0cf2193-8a87-5aed-86ac-7088255d507d', 'Liechtenstein Persons and Companies Law', 'Persons and Companies Law', 'The Persons and Companies Law in Liechtenstein, effective from 2024, establishes the legal framework governing individuals and corporate entities. It outlines the rights and responsibilities of natural and legal persons, including aspects of personal rights, civil status registration, and corporate governance. The law applies to all individuals and companies operating within Liechtenstein, mandating compliance with its provisions. Key requirements include the registration of civil status and adherence to obligations regarding corporate structure and governance. This law is mandatory for all entities within its jurisdiction.', 'The Persons and Companies Law in Liechtenstein, effective from 2024, establishes the legal framework governing individuals and corporate entities. It outlines the rights and responsibilities of natural and legal persons, including aspects of personal rights, civil status registration, and corporate governance. The law applies to all individuals and companies operating within Liechtenstein, mandating compliance with its provisions. Key requirements include the registration of civil status and adherence to obligations regarding corporate structure and governance. This law is mandatory for all entities within its jurisdiction.', 'The Persons and Companies Law in Liechtenstein, effective from 2024, establishes the legal framework governing individuals and corporate entities. It outlines the rights and responsibilities of natural and legal persons, including aspects of personal rights, civil status registration, and corporate governance. The law applies to all individuals and companies operating within Liechtenstein, mandating compliance with its provisions. Key requirements include the registration of civil status and adherence to obligations regarding corporate structure and governance. This law is mandatory for all entities within its jurisdiction.', 'Liechtenstein', 'governance', 'in_force', '2024-01-01'::date, 'Liechtenstein', 'https://www.carrotsandsticks.org/policies/204_3', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'liechtenstein', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b34c31eb-79ad-5701-ad1c-bb43a611c21c', 'Liechtenstein Disclosures Act', 'Disclosures Act', 'The Disclosures Act aims to protect investors and enhance transparency in the securities markets of Liechtenstein. It establishes requirements for the regular and ongoing disclosure of information by issuers of securities, including the publication of financial reports and information regarding significant shareholdings. This law applies to issuers whose securities are admitted to trading on a regulated market within the European Economic Area (EEA) and their shareholders. It is designed to implement EU directives on transparency requirements. The provisions are mandatory for the specified entities.', 'The Disclosures Act aims to protect investors and enhance transparency in the securities markets of Liechtenstein. It establishes requirements for the regular and ongoing disclosure of information by issuers of securities, including the publication of financial reports and information regarding significant shareholdings. This law applies to issuers whose securities are admitted to trading on a regulated market within the European Economic Area (EEA) and their shareholders. It is designed to implement EU directives on transparency requirements. The provisions are mandatory for the specified entities.', 'The Disclosures Act aims to protect investors and enhance transparency in the securities markets of Liechtenstein. It establishes requirements for the regular and ongoing disclosure of information by issuers of securities, including the publication of financial reports and information regarding significant shareholdings. This law applies to issuers whose securities are admitted to trading on a regulated market within the European Economic Area (EEA) and their shareholders. It is designed to implement EU directives on transparency requirements. The provisions are mandatory for the specified entities.', 'Liechtenstein', 'climate', 'in_force', '2024-01-01'::date, 'Liechtenstein', 'https://www.carrotsandsticks.org/policies/204_4', ARRAY['regulations', 'mandatory', 'liechtenstein', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41f9e3f7-182a-5f93-a731-0aabe54681b1', 'Liechtenstein Law of 10 November 2023 on the minimum', 'Law of 10 November 2023 on the minimum taxation of large corporate groups (GloBE Law)', 'The Law of 10 November 2023 in Liechtenstein establishes the minimum taxation of large corporate groups through additional taxes on domestic business units. It aligns with OECD/G20 guidelines and sets a minimum tax rate of 15%. The policy targets multinational and large domestic business groups.', 'The Law of 10 November 2023 in Liechtenstein establishes the minimum taxation of large corporate groups through additional taxes on domestic business units. It aligns with OECD/G20 guidelines and sets a minimum tax rate of 15%. The policy targets multinational and large domestic business groups.', 'The Law of 10 November 2023 in Liechtenstein establishes the minimum taxation of large corporate groups through additional taxes on domestic business units. It aligns with OECD/G20 guidelines and sets a minimum tax rate of 15%. The policy targets multinational and large domestic business groups.', 'Liechtenstein', 'governance', 'in_force', '2023-01-01'::date, 'Liechtenstein', 'https://www.carrotsandsticks.org/policies/204_2', ARRAY['mandatory', 'liechtenstein', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
