INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('17b17d79-5fde-5df6-830b-f5c78d38ac56', 'Lithuania Amendment of Articles 23, 26, 39, 40, 41', 'Law on Amendment of Articles 23, 26, 39, 40, 41, 42, 52, 71, 79, 140, 147, 148, 217, 219 of the Labour Code of The Republic of Lithuania', 'The "Law on Amendment of Articles 23, 26, 39, 40, 41, 42, 52, 71, 79, 140, 147, 148, 217, 219 of the Labour Code of The Republic of Lithuania" amends various labor code articles, focusing on wage discrimination, confidential information protection, and employee rights. It targets employers and employees in Lithuania to ensure fair labor practices.', 'The "Law on Amendment of Articles 23, 26, 39, 40, 41, 42, 52, 71, 79, 140, 147, 148, 217, 219 of the Labour Code of The Republic of Lithuania" amends various labor code articles, focusing on wage discrimination, confidential information protection, and employee rights. It targets employers and employees in Lithuania to ensure fair labor practices.', 'The "Law on Amendment of Articles 23, 26, 39, 40, 41, 42, 52, 71, 79, 140, 147, 148, 217, 219 of the Labour Code of The Republic of Lithuania" amends various labor code articles, focusing on wage discrimination, confidential information protection, and employee rights. It targets employers and employees in Lithuania to ensure fair labor practices.', 'Lithuania', 'social', 'in_force', '2025-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_6', ARRAY['sdg8', 'sdg10', 'regulations', 'mandatory', 'lithuania']::text[]) ON CONFLICT (id) DO NOTHING;
