INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9443759f-09de-51c5-a436-b980d4b5cb68', 'Lithuania Order No V3-14 on the inclusion of non-Member', 'Order No V3-14 on the inclusion of non-Member State auditors and non-Member State audit firms', 'Order No V3-14 establishes the procedures for registering auditors and audit firms from non-Member States in Lithuania. It applies to auditors and firms that have conducted audits of companies registered in third countries whose securities are publicly offered or traded in Lithuania. The order outlines the requirements for quality assurance checks and the registration process with the Lithuanian Ministry of Finance''s Audit, Accounting, Asset Valuation, and Insolvency Management Service. This policy is mandatory for relevant auditors and firms seeking registration.', 'Order No V3-14 establishes the procedures for registering auditors and audit firms from non-Member States in Lithuania. It applies to auditors and firms that have conducted audits of companies registered in third countries whose securities are publicly offered or traded in Lithuania. The order outlines the requirements for quality assurance checks and the registration process with the Lithuanian Ministry of Finance''s Audit, Accounting, Asset Valuation, and Insolvency Management Service. This policy is mandatory for relevant auditors and firms seeking registration.', 'Order No V3-14 establishes the procedures for registering auditors and audit firms from non-Member States in Lithuania. It applies to auditors and firms that have conducted audits of companies registered in third countries whose securities are publicly offered or traded in Lithuania. The order outlines the requirements for quality assurance checks and the registration process with the Lithuanian Ministry of Finance''s Audit, Accounting, Asset Valuation, and Insolvency Management Service. This policy is mandatory for relevant auditors and firms seeking registration.', 'Lithuania', 'social', 'in_force', '2024-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_13', ARRAY['guidance_frameworks', 'sdg10', 'mandatory', 'disclosure', 'lithuania']::text[]) ON CONFLICT (id) DO NOTHING;
